/** Tokens are base64url strings generated by the API; anything else is ignored. */
const TOKEN_PATTERN = /^[A-Za-z0-9_-]{20,200}$/;

/** Reads the reset token from a query string ("?reset=..."), returning null when it is unusable. */
export function resetTokenFromSearch(search: string): string | null {
  const query = search.startsWith("?") ? search : `?${search}`;
  const token = (new URLSearchParams(query).get("reset") || "").trim();
  return TOKEN_PATTERN.test(token) ? token : null;
}

/** Mirrors the API rule: at least 12 characters, and the confirmation must match. */
export function passwordProblem(password: string, confirmation?: string): string | null {
  if (password.length < 12) return "A senha deve ter pelo menos 12 caracteres.";
  if (password.length > 128) return "A senha deve ter no máximo 128 caracteres.";
  if (confirmation !== undefined && password !== confirmation) return "As senhas não coincidem.";
  return null;
}
